<template>
  <section class="preparation" aria-label="投放准备分析">
    <article class="prep-summary"><span class="prep-icon" aria-hidden="true">✦</span><div><p class="prep-label">小灵的建议</p><h3>{{ report?.summary.title || '先确认商品信息，再准备投放' }}</h3><p>{{ report?.summary.message || preparation?.summary || '我已整理商品基础信息与素材准备事项，需求场景及卖点还需你确认。' }}</p><small>{{ report?.summary.next_action || '当前依据为已选商品基础信息；市场趋势与历史投放表现需另行核验。' }}</small></div></article>
    <article v-if="products.length > 1" class="prep-group"><div class="prep-group-copy"><h3>商品组合建议</h3><p>{{ report?.combination.conclusion || '跨品类不代表不能合投，先确认目标和预算，再决定是否调整组合。' }}</p></div><div class="prep-group-points"><div><b>核对需求与场景</b><small>逐商品确认用途与素材方向</small></div><div><b>分别准备素材</b><small>不同创意独立测试与比较</small></div><div><b>目标设置后确认组合</b><small>结合经营目标、历史与测试预算</small></div></div><div class="prep-group-actions"><span class="prep-pending">{{ kept ? '已保留' : '待你确认' }}</span><button type="button" :aria-expanded="groupOpen" @click="groupOpen = !groupOpen">查看分组建议</button><button v-if="!readOnly" type="button" :disabled="busy || kept" @click="emit('keep')">{{ kept ? '已保留当前组合' : '保留当前组合' }}</button></div><div v-if="groupOpen" class="prep-groups"><p v-for="question in report?.combination.unanswered_questions || []" :key="question">待确认：{{ question }}</p><p v-if="!groups.length">当前没有足够依据提出具体分组，可以保留当前组合继续设置目标。</p><article v-for="group in groups" :key="group.name"><h4>{{ group.name }}</h4><p>{{ names(group.product_ids) }}</p><small>{{ group.reason }}</small><button v-if="group.product_ids.length < products.length && !readOnly" type="button" :disabled="busy" @click="emit('group', group.product_ids)">仅将这组商品保留在本计划</button></article><p>商品组合由你确认，此处不会自动创建其他草稿或计划。</p></div></article>
    <article class="prep-table"><h3>逐商品投放准备分析</h3><div class="prep-table-scroll"><table><thead><tr><th>商品</th><th>需求与场景（待验证）</th><th>素材方向</th><th>需你确认</th></tr></thead><tbody><template v-for="row in visibleRows" :key="row.product_id"><tr><td><div class="prep-product"><img v-if="row.image && !broken[row.product_id]" :src="row.image" alt="" @error="broken[row.product_id] = true" /><b>{{ row.name }}</b></div><button class="prep-detail-toggle" type="button" :aria-expanded="expandedProducts.includes(row.product_id)" @click="toggleProduct(row.product_id)">{{ expandedProducts.includes(row.product_id) ? '收起分析详情' : '查看分析详情' }}</button></td><td><span class="prep-fact-label">待验证场景</span>{{ row.demand_scene }}</td><td>{{ row.material_direction }}</td><td><ul><li v-for="check in row.confirmations.slice(0, 2)" :key="check">{{ check }}</li></ul></td></tr><tr v-if="expandedProducts.includes(row.product_id)"><td colspan="4" class="prep-details"><div class="prep-detail-grid"><section><b>已知事实</b><ul><li v-for="fact in row.report?.known_facts || []" :key="fact.statement">{{ fact.statement }}<small>依据：{{ evidenceText(fact.evidence_ids) }}</small></li></ul><p v-if="!row.report?.known_facts.length">历史分析未提供字段级证据，请核对当前商品信息。</p></section><section><b>创意假设 · 待验证</b><p v-for="hypothesis in row.report?.hypotheses || []" :key="hypothesis.need_or_scene">{{ hypothesis.need_or_scene }}<small>依据：{{ hypothesis.basis }}；验证方式：{{ hypothesis.validation_needed }}</small></p><p v-if="!row.report?.hypotheses.length">{{ row.demand_scene }}</p></section><section><b>素材准备要求</b><div v-for="direction in row.report?.creative_directions || []" :key="direction.title"><p>{{ direction.title }}：{{ direction.display_content }}</p><small>所需素材：{{ direction.required_assets.join('、') || '待确认' }}</small><small v-if="direction.pending_claims.length">待确认卖点：{{ direction.pending_claims.join('、') }}</small><small v-if="direction.avoid.length">不可直接使用：{{ direction.avoid.join('、') }}</small></div></section><section v-if="row.report?.historical_reference.length || row.report?.platform_reference.length"><b>历史与平台参考（非未来预测）</b><p v-for="reference in [...(row.report?.historical_reference || []), ...(row.report?.platform_reference || [])]" :key="reference.metric + reference.observed_period">{{ reference.metric_definition }}：{{ reference.value == null ? '缺少可计算口径' : `${reference.value}${reference.unit || ''}` }}<small>{{ reference.observed_period }} · {{ evidenceText(reference.evidence_ids) }}</small></p></section><section><b>该商品的市场依据</b><p v-for="market in report?.market_evidence.filter(m => m.product_ids.includes(row.product_id)) || []" :key="market.dimension">{{ market.missing_reason || market.observations.map(o => o.statement).join('；') || market.limitation }}</p></section><section><b>待补充与待确认</b><ul><li v-for="check in row.confirmations" :key="check">{{ check }}</li><li v-for="issue in row.report?.issues || []" :key="issue.code">{{ issue.severity === 'blocking' ? '需先处理：' : '' }}{{ issue.message }}；{{ issue.required_input }}</li></ul></section></div></td></tr></template></tbody></table></div><button v-if="rows.length > 3" type="button" class="prep-expand" @click="expanded = !expanded">{{ expanded ? '收起' : `其余 ${rows.length - 3} 款已收起，展开查看` }}</button></article>
    <article class="prep-market"><h3>市场竞争参考</h3><p>{{ marketMessage }}</p><details><summary>查看数据说明</summary><template v-for="(record, index) in report?.market_evidence || []" :key="index"><p v-for="observation in record.observations" :key="observation.statement">{{ observation.statement }}<small>依据：{{ evidenceText(observation.evidence_ids) }}</small></p><small v-if="record.availability !== 'unavailable'">适用范围：{{ Object.values(record.scope).filter(Boolean).join(' · ') }}</small><small>{{ record.limitation }}</small></template><section v-for="source in sources" :key="source.source_id" class="prep-source"><b>{{ source.provider }}{{ source.productNames ? ` · ${source.productNames}` : '' }}</b><small>{{ source.displayTime }} · {{ source.verified ? '来源适用范围已校验' : '待核验' }}</small><a v-if="source.link" :href="source.link" target="_blank" rel="noopener noreferrer">查看来源</a></section><p>公开搜索样本不能代表全市场或真实广告投放量，缺少对应时间窗的指标时不推断近7天趋势。</p><ul><li v-for="limit in report?.limitations || []" :key="limit">{{ limit }}</li></ul></details></article>
    <article class="prep-next"><h3>这些分析将用于下一步</h3><div><b>素材生成</b><p>按已确认的卖点准备差异化素材，候选场景用于创意测试，未确认宣传不自动用于文案。</p><details v-if="report"><summary>查看卖点与素材准备事项</summary><section v-for="item in report.handoff.material" :key="item.product_id"><b>{{ names([item.product_id]) }}</b><p>已确认可用事实：{{ item.approved_facts.map(f => f.statement).join('；') || '尚无已确认的宣传卖点，需核实后使用' }}</p><p>待确认：{{ item.pending_confirmation.join('；') }}</p><p>素材缺口：{{ item.required_assets.join('、') }}</p><small>不可直接使用：{{ item.blocked_claims.join('；') }}</small></section></details></div><div><b>预算评估</b><p>结合历史表现、平台建议和你的经营目标，确认测试预算。</p><details v-if="report"><summary>查看仍需提供的信息</summary><ul><li v-for="input in report.handoff.budget.required_inputs" :key="input">{{ input }}</li></ul></details></div><small>本次分析不包含未来 ROI 或成交预测。</small></article>
  </section>
</template>
<script setup lang="ts">
import { computed, ref } from 'vue';
import type { CreationProduct, ProductAnalysis } from '@/features/delivery/creationApi';
const props = defineProps<{ products: CreationProduct[]; analysis?: ProductAnalysis; busy: boolean; readOnly?: boolean; groupDecision?: string }>();
const emit = defineEmits<{ group: [ids: string[]]; keep: [] }>();
const report = computed(() => props.analysis?.selection_analysis), preparation = computed(() => props.analysis?.preparation);
const groupOpen = ref(false), expanded = ref(false), expandedProducts = ref<string[]>([]), broken = ref<Record<string, boolean>>({});
const kept = computed(() => props.groupDecision === 'KEEP_CURRENT');
const rows = computed(() => props.products.map(p => {
  const detail = report.value?.product_analyses.find(row => row.product_id === p.qcProductId);
  const legacy = preparation.value?.products.find(row => row.product_id === p.qcProductId);
  return { product_id: p.qcProductId, name: p.name, image: p.imageUrl, report: detail,
    demand_scene: detail?.hypotheses.map(h => h.need_or_scene).join('；') || legacy?.demand_scene || '需求及使用场景待验证，请结合商品实际用途确认。',
    material_direction: detail?.creative_directions.map(d => d.display_content).join('；') || legacy?.material_direction || '展示真实商品外观及已确认信息，准备不同方向的创意。',
    confirmations: detail?.confirmation_questions || legacy?.confirmations || ['确认推广SKU、实际价格与可使用的卖点'] };
}));
const visibleRows = computed(() => expanded.value ? rows.value : rows.value.slice(0, 3));
const groups = computed(() => {
  const supplied = report.value?.combination.proposed_groups.map(g => ({ name: g.group_id, product_ids: g.product_ids, reason: g.rationale })) || preparation.value?.group_suggestion.groups || [];
  return supplied.filter(g => g.product_ids.length && g.product_ids.every(id => props.products.some(p => p.qcProductId === id)));
});
const marketMessage = computed(() => report.value ? [...new Set(report.value.market_evidence.map(m => m.missing_reason || (m.availability !== 'unavailable' ? '以下观察仅适用于列明的统计范围与时间窗。' : m.limitation)))].join('；') || '本次没有可核验市场数据，不据此判断商品优劣。' : preparation.value?.market_reference.message || '暂未取得可核验的同类竞争与近7天趋势数据，不据此判断商品优劣。');
const names = (ids: string[]) => props.products.filter(p => ids.includes(p.qcProductId)).map(p => p.name).join('、');
const sources = computed(() => (props.analysis?.analysis_input?.sources || []).filter(source => report.value?.coverage.source_ids_used.includes(source.source_id)).map(source => {
  let link: string | undefined;
  try { const url = new URL(source.url || ''); if (['https:', 'http:'].includes(url.protocol) && !url.username && !url.password) link = url.href; } catch { /* Platform data does not require a public URL. */ }
  return { ...source, link, productNames: names(source.scope?.product_ids || []), displayTime: new Date(source.retrieved_at).toLocaleString('zh-CN', { timeZone: 'Asia/Shanghai', hour12: false }) };
}));
function evidenceText(ids: string[]) {
  const evidence = props.analysis?.analysis_input?.evidence || [];
  return [...new Set(ids.map(id => evidence.find(row => row.evidence_id === id)?.metric_definition || '历史快照中的商品信息'))].join('、');
}
function toggleProduct(id: string) { expandedProducts.value = expandedProducts.value.includes(id) ? expandedProducts.value.filter(x => x !== id) : [...expandedProducts.value, id]; }
</script>
<style scoped>
.preparation{display:grid;min-width:0;gap:14px;color:var(--color-text,#30344e)}.preparation article{min-width:0;border:1px solid var(--color-border,#ececf6);border-radius:14px;padding:22px;background:var(--color-surface,#fff)}.preparation h3{font-size:16px;font-weight:650;margin:0 0 8px}.preparation p{font-size:13px;color:var(--color-muted,#747990);line-height:1.8;margin:4px 0}.preparation small{display:block;font-size:12px;line-height:1.8;color:var(--color-muted,#868ba1)}.prep-summary{display:flex;gap:18px;background:var(--color-bg,#f7f6ff)!important}.prep-icon{font-size:30px;color:var(--color-primary,#575cf6)}.prep-label{color:var(--color-primary,#575cf6)!important;font-weight:600}.prep-group{display:flex;align-items:center;gap:20px;flex-wrap:wrap}.prep-group-copy{flex:1;min-width:200px}.prep-group-points{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px;flex:2}.prep-group-points>div{min-width:0;border-left:1px solid var(--color-border,#ececf6);padding-left:18px}.prep-group-points b,.prep-group-copy b{font-size:12px}.prep-group-actions{display:flex;gap:8px;flex-wrap:wrap;position:relative;padding-top:16px}.prep-pending{position:absolute;right:0;top:-8px;background:#fff1cc;color:#8a6416;padding:2px 8px;border-radius:4px;font-size:11px}.preparation button{padding:8px 12px;border:1px solid #dcdaf8;border-radius:7px;background:transparent;color:var(--color-primary,#575cf6);font-size:12px;cursor:pointer}.preparation button:disabled{opacity:.5;cursor:default}.prep-groups{flex-basis:100%;display:grid;gap:10px}.prep-groups article{padding:14px}.prep-groups h4{font-size:14px;font-weight:600}.prep-groups button{margin-top:10px}.prep-table-scroll{overflow:auto}table{width:100%;border-collapse:collapse;table-layout:fixed;font-size:12px;line-height:1.8}th,td{text-align:left;padding:12px;vertical-align:top;border-bottom:1px solid var(--color-border,#f0eff8);overflow-wrap:anywhere}th{background:var(--color-bg,#f7f7fc);color:var(--color-muted,#7f849a);font-size:12px;font-weight:500}th:first-child{width:19%}td ul{padding-left:16px;margin:0;list-style:disc}.prep-product{display:flex;align-items:center;gap:9px}.prep-product img{width:38px;height:38px;border-radius:4px;object-fit:cover}.prep-detail-toggle{border:0!important;padding:4px 0!important}.prep-fact-label{display:block;font-size:11px;color:var(--color-primary,#575cf6)}.prep-detail-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;background:var(--color-bg,#fafaff);padding:16px}.prep-detail-grid b{font-size:13px}.prep-expand{margin-top:12px}.preparation details summary{cursor:pointer;color:var(--color-primary,#575cf6);font-size:12px;margin-top:8px}.preparation details ul{font-size:12px;line-height:1.8;padding-left:18px;list-style:disc}.prep-market{display:flex;align-items:baseline;gap:20px;flex-wrap:wrap}.prep-market h3{margin:0;flex-shrink:0}.prep-market>p{flex:1;min-width:200px}.prep-market>details{flex-basis:100%}.prep-next{display:grid;grid-template-columns:1fr 1fr;gap:16px;background:var(--color-bg,#fafaff)!important}.prep-next h3,.prep-next>small{grid-column:1/-1}.prep-next b{font-size:13px}.prep-next details section,.prep-source{margin:12px 0}.prep-source a{font-size:12px;color:var(--color-primary,#575cf6);text-decoration:underline}@media(max-width:900px){.prep-group-points{flex-basis:100%}}@media(max-width:700px){.preparation article{padding:16px}.prep-next,.prep-detail-grid{grid-template-columns:1fr}.prep-table-scroll table{min-width:650px}.prep-group-points{gap:8px}.prep-group-points>div{padding-left:8px}}
</style>
